--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
    revoke trigger on cron.job_run_details from postgres;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
begin
    if not exists (
        select 1
        from pg_catalog.pg_event_trigger_ddl_commands() ev
        join pg_catalog.pg_extension e on ev.objid = e.oid
        where e.extname = 'pg_graphql'
    ) then
        return;
    end if;

    drop function if exists graphql_public.graphql;
    create or replace function graphql_public.graphql(
        "operationName" text default null,
        query text default null,
        variables jsonb default null,
        extensions jsonb default null
    )
        returns jsonb
        language sql
    as $$
        select graphql.resolve(
            query := query,
            variables := coalesce(variables, '{}'),
            "operationName" := "operationName",
            extensions := extensions
        );
    $$;

    -- Attach the wrapper to the extension so DROP EXTENSION cascades to it,
    -- which in turn triggers set_graphql_placeholder to reinstall the "not enabled" stub.
    alter extension pg_graphql add function graphql_public.graphql(text, text, jsonb, jsonb);

    grant usage on schema graphql to postgres, anon, authenticated, service_role;
    grant execute on function graphql.resolve to postgres, anon, authenticated, service_role;
    grant usage on schema graphql to postgres with grant option;
    grant usage on schema graphql_public to postgres with grant option;
end;
$_$;


--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8.0', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: -
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
            set search_path to ''
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: -
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: graphql(text, text, jsonb, jsonb); Type: FUNCTION; Schema: graphql_public; Owner: -
--

CREATE FUNCTION graphql_public.graphql("operationName" text DEFAULT NULL::text, query text DEFAULT NULL::text, variables jsonb DEFAULT NULL::jsonb, extensions jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: -
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


--
-- Name: admin_delete_user(text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_delete_user(p_email text, p_user_id uuid DEFAULT NULL::uuid, p_caller_email text DEFAULT NULL::text, p_admin_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_admin_email TEXT := COALESCE(NULLIF(TRIM(p_admin_email), ''), NULLIF(TRIM(p_caller_email), ''));
    v_caller_role TEXT := public.current_user_role();
    v_target_id UUID := p_user_id;
    v_current_users JSONB;
    v_updated_users JSONB;
    v_current_tombstones JSONB;
    v_auth_uid UUID;
BEGIN
    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        IF v_admin_email IS NOT NULL THEN
            SELECT role::text INTO v_caller_role
            FROM public.profiles
            WHERE LOWER(email) = LOWER(TRIM(v_admin_email)) AND is_active = true;
        END IF;
    END IF;

    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        RAISE EXCEPTION 'Access Denied (42501): Only administrators can delete users.';
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'on', true);

    UPDATE public.profiles
    SET is_deleted = true,
        is_active = false,
        updated_at = NOW()
    WHERE (v_clean_email IS NOT NULL AND LOWER(email) = v_clean_email)
       OR (v_target_id IS NOT NULL AND id = v_target_id)
    RETURNING id INTO v_target_id;

    IF v_target_id IS NOT NULL THEN
        DELETE FROM public.user_page_permissions WHERE user_id = v_target_id;
    END IF;

    SELECT id INTO v_auth_uid FROM auth.users WHERE LOWER(email) = v_clean_email LIMIT 1;
    IF v_auth_uid IS NOT NULL THEN
        DELETE FROM auth.users WHERE id = v_auth_uid;
    END IF;

    SELECT snapshot_data->'users', snapshot_data->'deletedUserIds'
    INTO v_current_users, v_current_tombstones
    FROM public.saved_records
    WHERE id = 'master_users_registry';

    IF v_current_users IS NOT NULL THEN
        SELECT jsonb_agg(u) INTO v_updated_users
        FROM jsonb_array_elements(v_current_users) u
        WHERE LOWER(u->>'email') <> v_clean_email
          AND (v_target_id IS NULL OR (u->>'id')::uuid <> v_target_id);

        IF v_updated_users IS NULL THEN
            v_updated_users := '[]'::jsonb;
        END IF;

        IF v_current_tombstones IS NULL THEN
            v_current_tombstones := '[]'::jsonb;
        END IF;

        IF NOT v_current_tombstones ? v_clean_email THEN
            v_current_tombstones := v_current_tombstones || jsonb_build_array(v_clean_email);
        END IF;

        UPDATE public.saved_records
        SET snapshot_data = jsonb_set(
                jsonb_set(snapshot_data, '{users}', v_updated_users),
                '{deletedUserIds}', v_current_tombstones
            ),
            updated_at = NOW()
        WHERE id = 'master_users_registry';
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'off', true);

    RETURN jsonb_build_object(
        'success', true,
        'deleted_email', v_clean_email,
        'deleted_user_id', v_target_id
    );
END;
$$;


--
-- Name: admin_provision_user(text, text, text, text, uuid, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_provision_user(p_email text, p_full_name text, p_role text, p_role_position text DEFAULT 'Operations Staff'::text, p_site_id uuid DEFAULT NULL::uuid, p_permitted_pages text[] DEFAULT ARRAY[]::text[], p_caller_email text DEFAULT NULL::text, p_admin_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_admin_email TEXT := COALESCE(NULLIF(TRIM(p_admin_email), ''), NULLIF(TRIM(p_caller_email), ''));
    v_caller_role TEXT := public.current_user_role();
    v_target_id UUID;
    v_clean_site_id UUID := p_site_id;
    v_default_dc_id UUID;
    v_page TEXT;
    v_current_users JSONB;
    v_updated_users JSONB;
    v_new_user_obj JSONB;
    v_now_iso TEXT := to_char(NOW() AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"');
BEGIN
    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        IF v_admin_email IS NOT NULL THEN
            SELECT role::text INTO v_caller_role
            FROM public.profiles
            WHERE LOWER(email) = LOWER(TRIM(v_admin_email)) AND is_active = true;
        END IF;
    END IF;

    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        RAISE EXCEPTION 'Access Denied (42501): Only administrators can provision users.';
    END IF;

    IF p_role = 'parts_management' THEN
        IF v_clean_site_id IS NULL THEN
            SELECT id INTO v_clean_site_id FROM public.sites WHERE code <> 'DC' AND is_active = true ORDER BY code LIMIT 1;
        END IF;
    ELSE
        IF v_clean_site_id IS NULL THEN
            SELECT id INTO v_default_dc_id FROM public.sites WHERE code = 'DC' LIMIT 1;
            v_clean_site_id := v_default_dc_id;
        END IF;
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'on', true);

        email,
        full_name,
        role,
        role_position,
        site_id,
        is_active,
        has_set_password,
        is_deleted,
        created_at,
        updated_at
    )
    VALUES (
        v_clean_email,
        p_full_name,
        p_role,
        p_role_position,
        v_clean_site_id,
        true,
        false,
        false,
        NOW(),
        NOW()
    )
    ON CONFLICT (email) DO UPDATE SET
        full_name = EXCLUDED.full_name,
        role = EXCLUDED.role,
        role_position = EXCLUDED.role_position,
        site_id = EXCLUDED.site_id,
        is_active = true,
        is_deleted = false,
        updated_at = NOW()
    RETURNING id INTO v_target_id;

    DELETE FROM public.user_page_permissions WHERE user_id = v_target_id;
    IF p_permitted_pages IS NOT NULL AND array_length(p_permitted_pages, 1) > 0 THEN
        FOREACH v_page IN ARRAY p_permitted_pages LOOP
            VALUES (v_target_id, v_page)
            ON CONFLICT (user_id, page_id) DO NOTHING;
        END LOOP;
    END IF;

    SELECT snapshot_data->'users' INTO v_current_users
    FROM public.saved_records
    WHERE id = 'master_users_registry';

    IF v_current_users IS NULL THEN
        v_current_users := '[]'::jsonb;
    END IF;

    SELECT jsonb_agg(u) INTO v_updated_users
    FROM jsonb_array_elements(v_current_users) u
    WHERE LOWER(u->>'email') <> v_clean_email;

    IF v_updated_users IS NULL THEN
        v_updated_users := '[]'::jsonb;
    END IF;

    v_new_user_obj := jsonb_build_object(
        'id', v_target_id,
        'email', v_clean_email,
        'fullName', p_full_name,
        'role', p_role,
        'rolePosition', p_role_position,
        'siteId', v_clean_site_id,
        'isActive', true,
        'hasSetPassword', false,
        'isDeleted', false,
        'permittedPages', to_jsonb(p_permitted_pages),
        'createdAt', v_now_iso,
        'updatedAt', v_now_iso
    );

    v_updated_users := v_updated_users || jsonb_build_array(v_new_user_obj);

    UPDATE public.saved_records
    SET snapshot_data = jsonb_set(
            jsonb_set(
                snapshot_data,
                '{users}',
                v_updated_users
            ),
            '{deletedUserIds}',
            (
                SELECT COALESCE(jsonb_agg(d), '[]'::jsonb)
                FROM jsonb_array_elements_text(COALESCE(snapshot_data->'deletedUserIds', '[]'::jsonb)) d
                WHERE LOWER(d) <> v_clean_email
            )
        ),
        updated_at = NOW()
    WHERE id = 'master_users_registry';

    PERFORM set_config('mdc.allow_profile_override', 'off', true);

    RETURN jsonb_build_object(
        'success', true,
        'user_id', v_target_id,
        'email', v_clean_email,
        'role', p_role,
        'site_id', v_clean_site_id
    );
END;
$$;


--
-- Name: admin_reset_user_password(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_user_password(p_email text, p_caller_email text DEFAULT NULL::text, p_new_password text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_caller_role TEXT := public.current_user_role();
    v_target_id UUID;
    v_current_users JSONB;
    v_updated_users JSONB;
    v_auth_uid UUID;
    v_new_hash TEXT := NULL;
    v_has_set_password BOOLEAN := false;
BEGIN
    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        IF p_caller_email IS NOT NULL THEN
            SELECT role::text INTO v_caller_role
            FROM public.profiles
            WHERE LOWER(email) = LOWER(TRIM(p_caller_email)) AND is_active = true;
        END IF;
    END IF;

    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        RAISE EXCEPTION 'Access Denied (42501): Only administrators can reset passwords.';
    END IF;

    IF p_new_password IS NOT NULL AND p_new_password <> '' THEN
        v_new_hash := 'sha256:' || encode(digest(('MDC_SECURE_SALT_2026_PRO:' || p_new_password || ':MDC_SECURE_SALT_2026_PRO')::bytea, 'sha256'), 'hex');
        v_has_set_password := true;
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'on', true);

    -- 1. Reset in public.profiles
    UPDATE public.profiles
    SET password_hash = v_new_hash,
        has_set_password = v_has_set_password,
        updated_at = NOW()
    WHERE LOWER(email) = v_clean_email
    RETURNING id INTO v_target_id;

    -- 2. Update auth.users if explicit password provided
    SELECT id INTO v_auth_uid FROM auth.users WHERE LOWER(email) = v_clean_email LIMIT 1;
    IF v_auth_uid IS NOT NULL AND p_new_password IS NOT NULL AND p_new_password <> '' THEN
        UPDATE auth.users
        SET encrypted_password = crypt(p_new_password, gen_salt('bf')),
            updated_at = NOW()
        WHERE id = v_auth_uid;
    END IF;

    -- 3. Sync to master_users_registry in saved_records
    SELECT snapshot_data->'users' INTO v_current_users
    FROM public.saved_records
    WHERE id = 'master_users_registry';

    IF v_current_users IS NOT NULL THEN
        SELECT jsonb_agg(
            CASE 
                WHEN LOWER(u->>'email') = v_clean_email THEN
                    jsonb_set(
                        jsonb_set(u, '{hasSetPassword}', to_jsonb(v_has_set_password)),
                        '{passwordHash}', 
                        CASE WHEN v_new_hash IS NOT NULL THEN to_jsonb(v_new_hash) ELSE 'null'::jsonb END
                    )
                ELSE u
            END
        ) INTO v_updated_users
        FROM jsonb_array_elements(v_current_users) u;

        UPDATE public.saved_records
        SET snapshot_data = jsonb_set(snapshot_data, '{users}', COALESCE(v_updated_users, v_current_users)),
            updated_at = NOW()
        WHERE id = 'master_users_registry';
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'off', true);

    RETURN jsonb_build_object(
        'success', true,
        'email', v_clean_email,
        'user_id', v_target_id,
        'reset_to_first_time', NOT v_has_set_password
    );
END;
$$;


--
-- Name: admin_reset_user_password(text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_reset_user_password(p_email text, p_new_password text DEFAULT NULL::text, p_require_setup boolean DEFAULT false, p_admin_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_caller_email TEXT := LOWER(COALESCE(auth.jwt() ->> 'email', TRIM(p_admin_email)));
    v_target_id UUID;
    v_hash TEXT := NULL;
    v_has_set BOOLEAN := false;
BEGIN
    -- 1. Authorization check: Superadmin or Admin can reset password
    IF public.current_user_role() NOT IN ('superadmin', 'admin') THEN
        IF v_caller_email IS NULL OR (
            NOT EXISTS (
                SELECT 1 FROM public.profiles
                WHERE LOWER(email) = v_caller_email
                  AND role IN ('superadmin', 'admin')
                  AND is_active = true
            )
            AND NOT EXISTS (
                SELECT 1 FROM public.saved_records sr,
                     jsonb_array_elements(COALESCE(sr.snapshot_data->'users', '[]'::jsonb)) u
                WHERE sr.id = 'master_users_registry'
                  AND LOWER(u->>'email') = v_caller_email
                  AND u->>'role' IN ('superadmin', 'admin')
                  AND COALESCE((u->>'isActive')::boolean, true) = true
            )
        ) THEN
            RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Only Superadmin or Admin can reset user passwords');
        END IF;
    END IF;

    -- 2. Find profile
    SELECT id INTO v_target_id FROM public.profiles WHERE LOWER(email) = v_clean_email LIMIT 1;
    IF v_target_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'User profile not found');
    END IF;

    -- 3. Calculate hash or mark setup required
    IF p_require_setup = true OR p_new_password IS NULL OR p_new_password = '' THEN
        v_has_set := false;
        v_hash := NULL;
    ELSE
        v_has_set := true;
        BEGIN
            v_hash := 'sha256:' || encode(digest(('MDC_SECURE_SALT_2026_PRO:' || p_new_password || ':MDC_SECURE_SALT_2026_PRO')::bytea, 'sha256'), 'hex');
        EXCEPTION WHEN OTHERS THEN
            v_hash := p_new_password;
        END;
    END IF;

    -- 4. Update profile
    UPDATE public.profiles
    SET has_set_password = v_has_set,
        password_hash = v_hash,
        updated_at = NOW()
    WHERE id = v_target_id;

    -- 5. Update saved_records (master_users_registry)
    BEGIN
        UPDATE public.saved_records
        SET snapshot_data = jsonb_set(
            COALESCE(snapshot_data, '{}'::jsonb),
            '{users}',
            COALESCE((
                SELECT jsonb_agg(
                    CASE WHEN LOWER(u->>'email') = v_clean_email OR u->>'id' = v_target_id::text
                    THEN jsonb_set(
                        jsonb_set(u, '{hasSetPassword}', to_jsonb(v_has_set)),
                        '{passwordHash}',
                        COALESCE(to_jsonb(v_hash), 'null'::jsonb)
                    )
                    ELSE u END
                )
                FROM jsonb_array_elements(COALESCE(snapshot_data->'users', '[]'::jsonb)) u
            ), '[]'::jsonb)
        ),
        updated_at = NOW()
        WHERE id = 'master_users_registry';
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'email', v_clean_email,
        'has_set_password', v_has_set
    );
END;
$$;


--
-- Name: admin_set_user_status(text, boolean, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_user_status(p_email text, p_is_active boolean, p_caller_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_caller_role TEXT := public.current_user_role();
    v_target_id UUID;
    v_current_users JSONB;
    v_updated_users JSONB;
BEGIN
    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        IF p_caller_email IS NOT NULL THEN
            SELECT role::text INTO v_caller_role
            FROM public.profiles
            WHERE LOWER(email) = LOWER(TRIM(p_caller_email)) AND is_active = true;
        END IF;
    END IF;

    IF v_caller_role NOT IN ('superadmin', 'admin') THEN
        RAISE EXCEPTION 'Access Denied (42501): Only administrators can change user status.';
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'on', true);

    -- 1. Update in public.profiles
    UPDATE public.profiles
    SET is_active = p_is_active,
        updated_at = NOW()
    WHERE LOWER(email) = v_clean_email
    RETURNING id INTO v_target_id;

    -- 2. Sync to master_users_registry in saved_records
    SELECT snapshot_data->'users' INTO v_current_users
    FROM public.saved_records
    WHERE id = 'master_users_registry';

    IF v_current_users IS NOT NULL THEN
        SELECT jsonb_agg(
            CASE 
                WHEN LOWER(u->>'email') = v_clean_email THEN
                    jsonb_set(u, '{isActive}', to_jsonb(p_is_active))
                ELSE u
            END
        ) INTO v_updated_users
        FROM jsonb_array_elements(v_current_users) u;

        UPDATE public.saved_records
        SET snapshot_data = jsonb_set(snapshot_data, '{users}', COALESCE(v_updated_users, v_current_users)),
            updated_at = NOW()
        WHERE id = 'master_users_registry';
    END IF;

    PERFORM set_config('mdc.allow_profile_override', 'off', true);

    RETURN jsonb_build_object(
        'success', true,
        'email', v_clean_email,
        'user_id', v_target_id,
        'is_active', p_is_active
    );
END;
$$;


--
-- Name: admin_update_user(uuid, text, text, text, text, uuid, boolean, text[], text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user(p_user_id uuid, p_email text, p_full_name text, p_role text, p_role_position text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid, p_is_active boolean DEFAULT true, p_permitted_pages text[] DEFAULT NULL::text[], p_admin_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_caller_email TEXT := LOWER(COALESCE(auth.jwt() ->> 'email', TRIM(p_admin_email)));
    v_target_id UUID := p_user_id;
    v_page TEXT;
BEGIN
    -- 1. Authorization check
    IF public.current_user_role() NOT IN ('superadmin', 'admin') THEN
        IF v_caller_email IS NULL OR (
            NOT EXISTS (
                SELECT 1 FROM public.profiles
                WHERE LOWER(email) = v_caller_email
                  AND role IN ('superadmin', 'admin')
                  AND is_active = true
            )
            AND NOT EXISTS (
                SELECT 1 FROM public.saved_records sr,
                     jsonb_array_elements(COALESCE(sr.snapshot_data->'users', '[]'::jsonb)) u
                WHERE sr.id = 'master_users_registry'
                  AND LOWER(u->>'email') = v_caller_email
                  AND u->>'role' IN ('superadmin', 'admin')
                  AND COALESCE((u->>'isActive')::boolean, true) = true
            )
        ) THEN
            RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Only Superadmin or Admin can update users');
        END IF;
    END IF;

    -- 2. Resolve target ID if needed
    IF v_target_id IS NULL AND v_clean_email IS NOT NULL AND v_clean_email <> '' THEN
        SELECT id INTO v_target_id FROM public.profiles WHERE LOWER(email) = v_clean_email LIMIT 1;
    END IF;

    IF v_target_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Target user profile not found');
    END IF;

    -- 3. Update public.profiles
    UPDATE public.profiles
    SET full_name = TRIM(p_full_name),
        role = p_role,
        role_position = COALESCE(p_role_position, role_position),
        site_id = COALESCE(p_site_id, site_id),
        is_active = COALESCE(p_is_active, is_active),
        updated_at = NOW()
    WHERE id = v_target_id;

    -- 4. Update permissions
    IF p_permitted_pages IS NOT NULL THEN
        DELETE FROM public.user_page_permissions WHERE user_id = v_target_id;
        FOREACH v_page IN ARRAY p_permitted_pages
        LOOP
            VALUES (v_target_id, v_page)
            ON CONFLICT (user_id, page_id) DO NOTHING;
        END LOOP;
    END IF;

    -- 5. Update saved_records (master_users_registry)
    BEGIN
        UPDATE public.saved_records
        SET snapshot_data = jsonb_set(
            COALESCE(snapshot_data, '{}'::jsonb),
            '{users}',
            COALESCE((
                SELECT jsonb_agg(
                    CASE WHEN LOWER(u->>'email') = v_clean_email OR u->>'id' = v_target_id::text
                    THEN jsonb_build_object(
                        'id', v_target_id,
                        'email', v_clean_email,
                        'fullName', TRIM(p_full_name),
                        'role', p_role,
                        'rolePosition', p_role_position,
                        'siteId', p_site_id,
                        'permittedPages', COALESCE(to_jsonb(p_permitted_pages), u->'permittedPages', '[]'::jsonb),
                        'hasSetPassword', COALESCE((u->>'hasSetPassword')::boolean, true),
                        'isActive', COALESCE(p_is_active, (u->>'isActive')::boolean, true)
                    )
                    ELSE u END
                )
                FROM jsonb_array_elements(COALESCE(snapshot_data->'users', '[]'::jsonb)) u
            ), '[]'::jsonb)
        ),
        updated_at = NOW()
        WHERE id = 'master_users_registry';
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;

    RETURN jsonb_build_object(
        'success', true,
        'id', v_target_id,
        'email', v_clean_email,
        'full_name', TRIM(p_full_name),
        'role', p_role,
        'role_position', p_role_position,
        'site_id', p_site_id,
        'is_active', p_is_active
    );
END;
$$;


--
-- Name: admin_update_user(uuid, text, text, text, text, uuid, boolean, text[], text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_update_user(p_user_id uuid DEFAULT NULL::uuid, p_email text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text, p_role text DEFAULT NULL::text, p_role_position text DEFAULT NULL::text, p_site_id uuid DEFAULT NULL::uuid, p_is_active boolean DEFAULT true, p_permitted_pages text[] DEFAULT NULL::text[], p_admin_email text DEFAULT NULL::text, p_caller_email text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_clean_email TEXT := LOWER(TRIM(p_email));
    v_caller_email TEXT := LOWER(COALESCE(auth.jwt() ->> 'email', TRIM(p_admin_email), TRIM(p_caller_email)));
    v_target_id UUID := p_user_id;
    v_page TEXT;
BEGIN
    -- 1. Authorization check: caller must be superadmin or admin
    IF public.current_user_role() NOT IN ('superadmin', 'admin') THEN
        IF v_caller_email IS NULL OR (
            NOT EXISTS (
                SELECT 1 FROM public.profiles
                WHERE LOWER(email) = v_caller_email
                  AND role IN ('superadmin', 'admin')
                  AND is_active = true
            )
            AND NOT EXISTS (
                SELECT 1 FROM public.saved_records sr,
                     jsonb_array_elements(COALESCE(sr.snapshot_data->'users', '[]'::jsonb)) u
                WHERE sr.id = 'master_users_registry'
                  AND LOWER(u->>'email') = v_caller_email
                  AND u->>'role' IN ('superadmin', 'admin')
                  AND COALESCE((u->>'isActive')::boolean, true) = true
            )
        ) THEN
            RETURN jsonb_build_object('success', false, 'error', 'Unauthorized: Only Superadmin or Admin can update users');
        END IF;
    END IF;

    -- 2. Resolve target ID if not provided
    IF v_target_id IS NULL AND v_clean_email IS NOT NULL AND v_clean_email <> '' THEN
        SELECT id INTO v_target_id FROM public.profiles WHERE LOWER(email) = v_clean_email LIMIT 1;
    END IF;

    -- If target ID provided but clean email missing, resolve email
    IF v_target_id IS NOT NULL AND (v_clean_email IS NULL OR v_clean_email = '') THEN
        SELECT LOWER(email) INTO v_clean_email FROM public.profiles WHERE id = v_target_id LIMIT 1;
    END IF;

    IF v_target_id IS NULL AND (v_clean_email IS NULL OR v_clean_email = '') THEN
        RETURN jsonb_build_object('success', false, 'error', 'Target user profile not found');
    END IF;

    -- 3. Set local session bypass for trigger execution
    PERFORM set_config('app.bypass_profile_integrity', 'on', true);

    -- 4. Update or Upsert in public.profiles
    IF v_target_id IS NOT NULL AND EXISTS (SELECT 1 FROM public.profiles WHERE id = v_target_id) THEN
        UPDATE public.profiles
        SET email = COALESCE(v_clean_email, email),
            full_name = COALESCE(TRIM(p_full_name), full_name),
            role = COALESCE(p_role::user_role, role),
            role_position = COALESCE(TRIM(p_role_position), role_position),
            site_id = p_site_id,
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        WHERE id = v_target_id;
    ELSIF v_clean_email IS NOT NULL AND EXISTS (SELECT 1 FROM public.profiles WHERE LOWER(email) = v_clean_email) THEN
        UPDATE public.profiles
        SET full_name = COALESCE(TRIM(p_full_name), full_name),
            role = COALESCE(p_role::user_role, role),
            role_position = COALESCE(TRIM(p_role_position), role_position),
            site_id = p_site_id,
            is_active = COALESCE(p_is_active, is_active),
            updated_at = NOW()
        WHERE LOWER(email) = v_clean_email
        RETURNING id INTO v_target_id;
    ELSE
        -- Insert new profile if not found
        v_target_id := COALESCE(v_target_id, gen_random_uuid());
            id, email, full_name, role, role_position, site_id, is_active, updated_at
        ) VALUES (
            v_target_id,
            v_clean_email,
            COALESCE(TRIM(p_full_name), v_clean_email),
            COALESCE(p_role::user_role, 'user'::user_role),
            TRIM(p_role_position),
            p_site_id,
            COALESCE(p_is_active, true),
            NOW()
        )
        ON CONFLICT (email) DO UPDATE
        SET full_name = EXCLUDED.full_name,
            role = EXCLUDED.role,
            role_position = EXCLUDED.role_position,
            site_id = EXCLUDED.site_id,
            is_active = EXCLUDED.is_active,
            updated_at = NOW()
        RETURNING id INTO v_target_id;
    END IF;

    -- 5. Update user permissions in public.user_page_permissions
    IF p_permitted_pages IS NOT NULL AND v_target_id IS NOT NULL THEN
        DELETE FROM public.user_page_permissions WHERE user_id = v_target_id;
        FOREACH v_page IN ARRAY p_permitted_pages
        LOOP
            VALUES (v_target_id, v_page)
            ON CONFLICT (user_id, page_id) DO NOTHING;
        END LOOP;
    END IF;

    -- 6. Keep public.saved_records (master_users_registry) synchronized
    BEGIN
        UPDATE public.saved_records
        SET snapshot_data = jsonb_set(
            COALESCE(snapshot_data, '{}'::jsonb),
            '{users}',
            COALESCE((
                SELECT jsonb_agg(
                    CASE WHEN LOWER(u->>'email') = v_clean_email OR u->>'id' = v_target_id::text
                    THEN jsonb_build_object(
                        'id', v_target_id,
                        'email', v_clean_email,
                        'fullName', COALESCE(TRIM(p_full_name), u->>'fullName'),
                        'role', COALESCE(p_role, u->>'role'),
                        'rolePosition', COALESCE(TRIM(p_role_position), u->>'rolePosition'),
                        'siteId', p_site_id,
                        'permittedPages', COALESCE(to_jsonb(p_permitted_pages), u->'permittedPages', '[]'::jsonb),
                        'hasSetPassword', COALESCE((u->>'hasSetPassword')::boolean, true),
                        'isActive', COALESCE(p_is_active, (u->>'isActive')::boolean, true)
                    )
                    ELSE u END
                )
                FROM jsonb_array_elements(COALESCE(snapshot_data->'users', '[]'::jsonb)) u
            ), '[]'::jsonb)
        ),
        updated_at = NOW()
        WHERE id = 'master_users_registry';
    EXCEPTION WHEN OTHERS THEN
        NULL;
    END;

    -- 7. Reset the local bypass config
    PERFORM set_config('app.bypass_profile_integrity', 'off', true);

    RETURN jsonb_build_object(
        'success', true,
        'id', v_target_id,
        'email', v_clean_email,
        'full_name', TRIM(p_full_name),
        'role', p_role,
        'role_position', p_role_position,
        'site_id', p_site_id,
        'is_active', p_is_active
    );
END;
$$;


--
-- Name: create_or_update_shipment_with_items(jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_or_update_shipment_with_items(p_shipment jsonb, p_items jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_shipment_id UUID;
    v_item JSONB;
BEGIN
    -- 1. Insert or update shipment header using shipment_number
        id,
        shipment_number,
        invoice_ref,
        site_id,
        allocation_cycle_id,
        week_number,
        shipment_date,
        carrier,
        tracking_number,
        total_boxes,
        status,
        prepared_by_name,
        verified_by_name,
        receiving_signature,
        remarks,
        created_by,
        updated_at
    ) VALUES (
        COALESCE(NULLIF(p_shipment->>'id', '')::UUID, gen_random_uuid()),
        p_shipment->>'shipment_number',
        p_shipment->>'invoice_ref',
        (p_shipment->>'site_id')::UUID,
        NULLIF(p_shipment->>'allocation_cycle_id', '')::UUID,
        COALESCE((p_shipment->>'week_number')::INT, 1),
        COALESCE((p_shipment->>'shipment_date')::DATE, CURRENT_DATE),
        COALESCE(p_shipment->>'carrier', 'Lite Express'),
        p_shipment->>'tracking_number',
        COALESCE((p_shipment->>'total_boxes')::INT, 1),
        COALESCE(p_shipment->>'status', 'draft'),
        p_shipment->>'prepared_by_name',
        p_shipment->>'verified_by_name',
        p_shipment->>'receiving_signature',
        p_shipment->>'remarks',
        NULLIF(p_shipment->>'created_by', '')::UUID,
        NOW()
    )
    ON CONFLICT (shipment_number) DO UPDATE SET
        status = EXCLUDED.status,
        total_boxes = EXCLUDED.total_boxes,
        carrier = EXCLUDED.carrier,
        tracking_number = EXCLUDED.tracking_number,
        remarks = EXCLUDED.remarks,
        updated_at = NOW()
    RETURNING id INTO v_shipment_id;

    -- 2. Insert items only after header exists
    IF p_items IS NOT NULL AND jsonb_array_length(p_items) > 0 THEN
        FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
                id,
                shipment_id,
                inventory_unit_id,
                part_id,
                serial_number,
                box_number,
                scanned_at,
                scanned_by
            ) VALUES (
                COALESCE(NULLIF(v_item->>'id', '')::UUID, gen_random_uuid()),
                v_shipment_id,
                NULLIF(v_item->>'inventory_unit_id', '')::UUID,
                (v_item->>'part_id')::UUID,
                v_item->>'serial_number',
                COALESCE((v_item->>'box_number')::INT, 1),
                COALESCE((v_item->>'scanned_at')::TIMESTAMPTZ, NOW()),
                NULLIF(v_item->>'scanned_by', '')::UUID
            )
            ON CONFLICT (id) DO UPDATE SET
                box_number = EXCLUDED.box_number,
                scanned_at = EXCLUDED.scanned_at;
        END LOOP;
    END IF;

    RETURN v_shipment_id;
END;
$$;


--
-- Name: create_parts_request(uuid, uuid, integer, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_parts_request(p_site_id uuid, p_part_id uuid, p_quantity integer, p_priority text DEFAULT 'normal'::text, p_reason text DEFAULT 'Site replenishment request'::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_caller_profile RECORD;
    v_target_site RECORD;
    v_target_part RECORD;
    v_is_fulfillment_role BOOLEAN;
    v_prefix TEXT;
    v_seq_num INT;
    v_request_number TEXT;
    v_new_request RECORD;
BEGIN
    -- 1. Validate quantity
    IF p_quantity IS NULL OR p_quantity <= 0 THEN
        RAISE EXCEPTION 'Requested quantity must be greater than zero (received %)', p_quantity;
    END IF;

    -- 2. Validate priority
    IF p_priority NOT IN ('normal', 'urgent', 'critical') THEN
        p_priority := 'normal';
    END IF;

    -- 3. Resolve caller identity
    SELECT * INTO v_caller_profile
    FROM public.profiles
    WHERE id = auth.uid() AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Authenticated user profile not found or account is deactivated';
    END IF;

    -- 4. Validate target site exists
    SELECT * INTO v_target_site
    FROM public.sites
    WHERE id = p_site_id AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Target site % not found or inactive', p_site_id;
    END IF;

    -- 5. Validate target part exists
    SELECT * INTO v_target_part
    FROM public.parts
    WHERE id = p_part_id AND is_active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Target part % not found or inactive', p_part_id;
    END IF;

    -- 6. Enforce role boundary (Defense-in-depth on top of RLS)
    v_is_fulfillment_role := v_caller_profile.role IN ('superadmin', 'admin', 'planner', 'warehouse_staff', 'logistics_staff');
    
    IF NOT v_is_fulfillment_role THEN
        IF v_caller_profile.site_id IS NULL OR v_caller_profile.site_id <> p_site_id THEN
            RAISE EXCEPTION 'Permission Denied: Staff accounts can only submit parts requests for their assigned branch site';
        END IF;
    END IF;

    -- 7. Generate sequential human-readable request number (PR-YYYYMM-00001) atomically
    v_prefix := 'PR-' || TO_CHAR(NOW(), 'YYYYMM') || '-';

    -- Query current max sequence for the month with row lock
    SELECT COALESCE(
        MAX(
            CASE 
                WHEN request_number LIKE v_prefix || '%' AND LENGTH(request_number) >= LENGTH(v_prefix) + 5
                THEN SUBSTRING(request_number FROM LENGTH(v_prefix) + 1)::INT
                ELSE 0
            END
        ), 0
    ) + 1 INTO v_seq_num
    FROM public.parts_requests
    WHERE request_number LIKE v_prefix || '%';

    v_request_number := v_prefix || LPAD(v_seq_num::TEXT, 5, '0');

    -- 8. Insert parts_requests row
        request_number,
        site_id,
        part_id,
        quantity_requested,
        quantity_fulfilled,
        status,
        priority,
        requested_by,
        requested_by_name,
        reason,
        notes,
        created_at,
        updated_at
    ) VALUES (
        v_request_number,
        p_site_id,
        p_part_id,
        p_quantity,
        0,
        'pending',
        p_priority,
        v_caller_profile.id,
        COALESCE(v_caller_profile.full_name, 'MobileCare Staff'),
        COALESCE(TRIM(p_reason), 'Site replenishment request'),
        NULLIF(TRIM(p_notes), ''),
        NOW(),
        NOW()
    )
    RETURNING * INTO v_new_request;

    -- 9. Append-only audit log entry
        action,
        entity_type,
        entity_id,
        entity_label,
        user_id,
        user_name,
        user_email,
        user_role,
        metadata
    ) VALUES (
        'PARTS_REQUEST_CREATED',
        'parts_requests',
        v_new_request.id::TEXT,
        v_request_number || ' (' || v_target_part.part_number || ' x' || p_quantity || ')',
        v_caller_profile.id,
        v_caller_profile.full_name,
        v_caller_profile.email,
        v_caller_profile.role::TEXT,
        jsonb_build_object(
            'request_number', v_request_number,
            'site_code', v_target_site.code,
            'site_name', v_target_site.name,
            'part_number', v_target_part.part_number,
            'part_description', v_target_part.description,
            'quantity_requested', p_quantity,
            'priority', p_priority,
            'reason', p_reason
        )
    );

    RETURN jsonb_build_object(
        'success', true,
        'id', v_new_request.id,
        'request_number', v_request_number,
        'status', v_new_request.status,
        'created_at', v_new_request.created_at
    );
END;
$$;


--
-- Name: current_user_role(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_role() RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_role TEXT;
BEGIN
    -- 1. Direct match on profiles.id = auth.uid()
    SELECT role::text INTO v_role
    FROM public.profiles
    WHERE id = auth.uid() AND is_active = true
    LIMIT 1;

    IF v_role IS NOT NULL THEN
        RETURN v_role;
    END IF;

    -- 2. Fallback: match by email from authenticated JWT session
    IF auth.jwt() ->> 'email' IS NOT NULL THEN
        SELECT role::text INTO v_role
        FROM public.profiles
        WHERE LOWER(email) = LOWER(auth.jwt() ->> 'email') AND is_active = true
        LIMIT 1;

        IF v_role IS NOT NULL THEN
            RETURN v_role;
        END IF;
    END IF;

    -- 3. Fallback: user_metadata in JWT
    v_role := auth.jwt() -> 'user_metadata' ->> 'role';
    IF v_role IS NOT NULL THEN
        RETURN v_role;
    END IF;

    -- 4. Default for unauthenticated/anon
    RETURN 'anon';
END;
$$;


--
-- Name: current_user_site_id(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_site_id() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $_$
DECLARE
    v_site_id UUID;
    v_meta_site TEXT;
BEGIN
    -- 1. Direct match on profiles.id = auth.uid()
    SELECT site_id INTO v_site_id
    FROM public.profiles
    WHERE id = auth.uid() AND is_active = true
    LIMIT 1;

    IF v_site_id IS NOT NULL THEN
        RETURN v_site_id;
    END IF;

    -- 2. Fallback: match by email from authenticated JWT session
    IF auth.jwt() ->> 'email' IS NOT NULL THEN
        SELECT site_id INTO v_site_id
        FROM public.profiles
        WHERE LOWER(email) = LOWER(auth.jwt() ->> 'email') AND is_active = true
        LIMIT 1;

        IF v_site_id IS NOT NULL THEN
            RETURN v_site_id;
        END IF;
    END IF;

    -- 3. Fallback: user_metadata in JWT (validated with UUID regex)
    v_meta_site := auth.jwt() -> 'user_metadata' ->> 'site_id';
    IF v_meta_site IS NOT NULL AND v_meta_site ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
        RETURN v_meta_site::UUID;
    END IF;

    RETURN NULL;
END;
$_$;


--
-- Name: enforce_profile_update_integrity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_profile_update_integrity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    -- Bypass 1: Execution inside an authorized administrative RPC setting the local session bypass
    IF CURRENT_SETTING('app.bypass_profile_integrity', true) = 'on' THEN
        RETURN NEW;
    END IF;

    -- Bypass 2: Superuser, supabase admin, or service_role connection
    IF CURRENT_USER IN ('postgres', 'supabase_admin', 'service_role') THEN
        RETURN NEW;
    END IF;

    -- Bypass 3: Authenticated superadmin or admin session
    IF public.current_user_role() IN ('superadmin', 'admin') THEN
        RETURN NEW;
    END IF;

    -- Privilege escalation defense: non-admin users cannot alter their role
    IF NEW.role IS DISTINCT FROM OLD.role THEN
        RAISE EXCEPTION 'Access Denied (42501): Unauthorized role modification.'
            USING ERRCODE = '42501';
    END IF;

    -- Branch manipulation defense: non-admin users cannot alter their assigned site_id
    IF NEW.site_id IS DISTINCT FROM OLD.site_id THEN
        RAISE EXCEPTION 'Access Denied (42501): Unauthorized site modification.'
            USING ERRCODE = '42501';
    END IF;

    -- Account status manipulation defense: non-admin users cannot alter active status
    IF NEW.is_active IS DISTINCT FROM OLD.is_active THEN
        RAISE EXCEPTION 'Access Denied (42501): Unauthorized account status modification.'
            USING ERRCODE = '42501';
    END IF;

    -- Account deletion status defense: non-admin users cannot undelete accounts
    IF NEW.is_deleted IS DISTINCT FROM OLD.is_deleted THEN
        RAISE EXCEPTION 'Access Denied (42501): Unauthorized account deletion status modification.'
            USING ERRCODE = '42501';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: get_all_active_users(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_all_active_users() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'pg_temp'
    AS $$
DECLARE
    v_result JSONB;
BEGIN
    SELECT jsonb_agg(
        jsonb_build_object(
            'id', p.id,
            'user_id', p.id,
            'email', p.email,
            'full_name', p.full_name,
            'fullName', p.full_name,
            'role', p.role,
            'role_position', p.role_position,
            'rolePosition', p.role_position,
            'site_id', p.site_id,
            'siteId', p.site_id,
            'is_active', p.is_active,
            'isActive', p.is_active,
            'is_deleted', p.is_deleted,
            'has_set_password', p.has_set_password,
            'hasSetPassword', p.has_set_password,
            'permittedPages', COALESCE(
                (SELECT array_agg(page_id) FROM public.user_page_permissions WHERE user_id = p.id),
                ARRAY[]::TEXT[]
            )
        ) ORDER BY p.created_at ASC
    ) INTO v_result
    FROM public.profiles p
    WHERE p.is_deleted = false;

    RETURN COALESCE(v_result, '[]'::jsonb);
END;
$$;


--
-- Name: get_saved_period_records(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_saved_period_records() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_records JSONB;
BEGIN
    SELECT jsonb_agg(to_jsonb(r.*) ORDER BY r.created_at DESC)
    INTO v_records
    FROM public.saved_records r
    WHERE (r.record_type IN ('both', 'forecast', 'allocation', 'period_record', 'historical_archive') OR r.id LIKE 'rec-%')
      AND r.notes <> '__DELETED__'
      AND COALESCE((r.snapshot_data->>'isDeleted')::boolean, false) = false;

    RETURN COALESCE(v_records, '[]'::jsonb);
END;
$$;


