--
-- Name: view_repair_usage_in_scope; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_repair_usage_in_scope WITH (security_invoker='true') AS
 SELECT id,
    import_batch_id,
    month_name,
    closed_date,
    site_id,
    part_id,
    raw_part_number,
    raw_part_description,
    raw_site_name,
    repair_number,
    order_id,
    kgb_kbb_number,
    quantity,
    created_at,
    repair_closed_date,
    raw_row_ref,
    is_in_scope,
        CASE
            WHEN (lower(raw_part_description) ~~ '%display%'::text) THEN 'DISPLAY'::text
            WHEN (lower(raw_part_description) ~~ '%battery%'::text) THEN 'BATTERY'::text
            ELSE 'OTHER'::text
        END AS commodity_group
   FROM public.repair_usage_records r
  WHERE ((raw_part_description ~~* '%iphone%'::text) AND ((raw_part_description ~~* '%battery%'::text) OR (raw_part_description ~~* '%display%'::text)) AND (lower(TRIM(BOTH FROM raw_part_description)) <> ALL (ARRAY['battery, iphone 11'::text, 'battery, iphone 8'::text, 'battery, iphone 11 pro'::text, 'battery, iphone 11 pro max'::text, 'battery, iphone 12 and 12 pro'::text, 'battery, iphone 12 mini'::text, 'battery, iphone 12 pro max'::text, 'battery, iphone 13 mini'::text, 'battery, iphone 8 plus'::text, 'battery, iphone se 2nd gen'::text, 'battery, iphone se 3rd generation'::text, 'battery, iphone x'::text, 'battery, iphone xr'::text, 'display, iphone 11'::text, 'display, iphone 12'::text, 'display, iphone 12 mini'::text, 'display, iphone 12 pro'::text, 'display, iphone 12 pro max'::text, 'display, iphone 13 mini'::text, 'display, iphone xr'::text])));


--
-- Name: VIEW view_repair_usage_in_scope; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.view_repair_usage_in_scope IS 'Filtered in-scope repair universe with security_invoker enabled.';


--
-- Name: view_monthly_part_usage; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_monthly_part_usage WITH (security_invoker='true') AS
 SELECT raw_part_number,
    raw_part_description,
    commodity_group,
    EXTRACT(year FROM repair_closed_date) AS repair_year,
    EXTRACT(month FROM repair_closed_date) AS month_number,
    month_name,
    sum(quantity) AS total_usage_count
   FROM public.view_repair_usage_in_scope
  WHERE (repair_closed_date IS NOT NULL)
  GROUP BY raw_part_number, raw_part_description, commodity_group, (EXTRACT(year FROM repair_closed_date)), (EXTRACT(month FROM repair_closed_date)), month_name
  ORDER BY commodity_group, raw_part_description, (EXTRACT(year FROM repair_closed_date)), (EXTRACT(month FROM repair_closed_date));


--
-- Name: VIEW view_monthly_part_usage; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.view_monthly_part_usage IS 'Monthly part usage summary with security_invoker enabled.';


--
-- Name: view_part_site_shares; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.view_part_site_shares WITH (security_invoker='true') AS
 WITH part_site_counts AS (
         SELECT r.raw_part_number,
            r.raw_part_description,
            r.commodity_group,
            COALESCE(s.code, r.raw_site_name) AS site_code,
            COALESCE(s.name, r.raw_site_name) AS site_name,
            sum(r.quantity) AS site_usage_count
           FROM (public.view_repair_usage_in_scope r
             LEFT JOIN public.sites s ON (((r.site_id = s.id) OR (upper(r.raw_site_name) = upper(s.name)) OR (upper(r.raw_site_name) = upper(s.code)))))
          GROUP BY r.raw_part_number, r.raw_part_description, r.commodity_group, COALESCE(s.code, r.raw_site_name), COALESCE(s.name, r.raw_site_name)
        ), part_totals AS (
         SELECT part_site_counts.raw_part_description,
            sum(part_site_counts.site_usage_count) AS part_total_usage
           FROM part_site_counts
          GROUP BY part_site_counts.raw_part_description
        )
 SELECT psc.raw_part_number,
    psc.raw_part_description,
    psc.commodity_group,
    psc.site_code,
    psc.site_name,
    psc.site_usage_count,
    pt.part_total_usage,
        CASE
            WHEN (pt.part_total_usage > (0)::numeric) THEN round(((psc.site_usage_count)::numeric / pt.part_total_usage), 6)
            ELSE (0)::numeric
        END AS all_time_share_pct
   FROM (part_site_counts psc
     JOIN part_totals pt ON ((psc.raw_part_description = pt.raw_part_description)))
  ORDER BY psc.commodity_group, psc.raw_part_description, psc.site_code;


--
-- Name: VIEW view_part_site_shares; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.view_part_site_shares IS 'All-time site allocation shares with security_invoker enabled.';


