--
-- Name: profiles profiles_update_guarded; Type: POLICY; Schema: public; Owner: -
--

CREATE POLICY profiles_update_guarded ON public.profiles FOR UPDATE TO authenticated, anon USING (((public.current_user_role() = ANY (ARRAY['superadmin'::text, 'admin'::text])) OR (id = auth.uid()) OR (lower(email) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text))))) WITH CHECK (((public.current_user_role() = ANY (ARRAY['superadmin'::text, 'admin'::text])) OR (((id = auth.uid()) OR (lower(email) = lower(COALESCE((auth.jwt() ->> 'email'::text), ''::text)))) AND (NOT (role IS DISTINCT FROM ( SELECT p.role
   FROM public.profiles p
  WHERE (p.id = profiles.id)))) AND (NOT (site_id IS DISTINCT FROM ( SELECT p.site_id
   FROM public.profiles p
  WHERE (p.id = profiles.id)))) AND (NOT (is_active IS DISTINCT FROM ( SELECT p.is_active
   FROM public.profiles p
  WHERE (p.id = profiles.id)))))));


